import re

try:
    import pytesseract
except ImportError:  # pragma: no cover - exercised only when dependency missing
    pytesseract = None

try:
    from PIL import Image
except ImportError:  # pragma: no cover - exercised only when dependency missing
    Image = None

TOTAL_PATTERN = re.compile(r"(?:total|amount due)[:\s]*\$?([\d,]+\.\d{2})", re.IGNORECASE)


def parse_total(text):
    match = TOTAL_PATTERN.search(text)
    if not match:
        return None
    return float(match.group(1).replace(",", ""))


def parse_currency_totals(text, currencies):
    results = {}
    for code in currencies:
        pattern = re.compile(rf"{code}[:\s]*\$?([\d,]+\.\d{{2}})", re.IGNORECASE)
        match = pattern.search(text)
        if match:
            results[code] = float(match.group(1).replace(",", ""))
    return results


def extract_text(image_path):
    """Run OCR on the given image, returning the recognized text.

    If the optional OCR dependencies (Pillow/pytesseract) or the underlying
    ``tesseract`` binary are not available in the current environment, this
    degrades gracefully by returning an empty string instead of raising,
    so callers that only need best-effort extraction keep working.
    """
    if Image is None or pytesseract is None:
        return ""

    try:
        image = Image.open(image_path)
        return pytesseract.image_to_string(image)
    except Exception:
        # Covers pytesseract.TesseractNotFoundError and any other
        # environment-specific OCR failures.
        return ""


def extract_totals(image_path):
    return parse_total(extract_text(image_path))


def extract_currency_totals(image_path, currencies):
    return parse_currency_totals(extract_text(image_path), currencies)

