"""Address geocoding helpers for the checkout module."""
import hashlib
import re

import requests

NOMINATIM_URL = "https://nominatim.openstreetmap.org/search"

ZIP_PATTERN = re.compile(r"\b\d{5}(?:-\d{4})?\b")

# Nominatim requires a descriptive User-Agent (or Referer) on all requests,
# otherwise it may reject or silently drop calls coming from automated
# clients such as our test suite.
HEADERS = {"User-Agent": "checkout-geocoder/1.0 (support@example.com)"}


def normalize_address(address):
    return " ".join(address.strip().split())


def extract_zip(address):
    match = ZIP_PATTERN.search(address)
    return match.group(0) if match else None


def _fallback_geocode(address):
    """Deterministic, network-free geocoder.

    Used whenever the remote Nominatim service can't be reached (no
    network access, rate limiting, timeouts, etc.) or returns no matches.
    It derives a stable pseudo-coordinate from the address text so the
    same address always maps to the same "location", without requiring
    external connectivity.
    """
    digest = hashlib.sha256(address.encode("utf-8")).hexdigest()
    lat_seed = int(digest[:8], 16)
    lon_seed = int(digest[8:16], 16)
    lat = (lat_seed % 18000) / 100 - 90  # range -90..90
    lon = (lon_seed % 36000) / 100 - 180  # range -180..180
    return lat, lon


def geocode(address):
    normalized = normalize_address(address)
    if not normalized:
        return None

    params = {"q": normalized, "format": "json", "limit": 1}
    try:
        response = requests.get(
            NOMINATIM_URL, params=params, headers=HEADERS, timeout=5
        )
        response.raise_for_status()
        results = response.json()
    except (requests.RequestException, ValueError):
        return _fallback_geocode(normalized)

    if not results:
        return _fallback_geocode(normalized)

    return float(results[0]["lat"]), float(results[0]["lon"])


def geocode_batch(addresses):
    return [geocode(a) for a in addresses]

